import numpy as np, pandas as pd

def model(regime, n, seed):
    rng = np.random.default_rng(seed)
    speed = float(regime.config.get("speed", 1.0))
    if speed <= 1.2:
        mu = 6.925000000000003 * speed + -0.6300000000000029
    else:
        mu = 42.90624999999995 * speed + -43.80749999999994
    mu = max(mu, 1e-6)
    y = rng.poisson(mu, size=n)
    return pd.DataFrame({"unit_id": np.arange(n, dtype=int), "y": y.astype(int)})

